package com.security.__PKG__.ui.components

// Canonical source: android-foundation/design-system/components/GlassPill.kt
// Copied into every app generated by `app`, with __PKG__ replaced (and the theme package
// adjusted if the app keeps its tokens elsewhere, e.g. Donova's ui/). Improve it in
// android-foundation, not in a single app.

import androidx.compose.foundation.border
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Shape
import androidx.compose.ui.unit.dp
import com.kyant.backdrop.Backdrop
import com.kyant.backdrop.backdrops.emptyBackdrop
import com.kyant.backdrop.drawBackdrop
import com.kyant.backdrop.effects.blur
import com.security.__PKG__.ui.theme.Accent
import com.security.__PKG__.ui.theme.LocalScreenBackdrop
import com.security.__PKG__.ui.theme.wallpaperBackdropActive

/**
 * The [GlassFab] look for small pills (count badges, segmented-control indicator): a blurred copy
 * (12.dp) of [blurSource] under a 12 % [tint] wash, drawBackdrop's rim highlight and a 50 % [tint]
 * outline.
 *
 * Always drawn through drawBackdrop — emptyBackdrop() when [blurSource] is null — so every pill
 * gets the same rim, whether or not it has anything to blur. [blurSource] must never be a backdrop
 * that records the pill itself (e.g. the list backdrop for a pill inside that list): that draws
 * the layer into itself. See [pillBlurSource] for the safe default.
 */
fun Modifier.glassPill(
    blurSource: Backdrop?,
    tint: Color = Accent,
    shape: Shape = RoundedCornerShape(percent = 50),
): Modifier = this
    .drawBackdrop(
        backdrop      = blurSource ?: emptyBackdrop(),
        shape         = { shape },
        effects       = { blur(12.dp.toPx()) },
        onDrawSurface = { drawRect(tint.copy(alpha = 0.12f)) },
    )
    .border(1.dp, tint.copy(alpha = 0.5f), shape)

/** Default [glassPill] source for pills inside recorded content: the wallpaper, when there is one. */
@Composable
fun pillBlurSource(): Backdrop? = LocalScreenBackdrop.current?.takeIf { wallpaperBackdropActive }
